---@class ExhibitBoxInfo
ExhibitBoxInfo = class("ExhibitBoxInfo")

function ExhibitBoxInfo:initialize()
    ---@type IBox
    self.IBox = nil
    self.serverID = -1
    self.slotID = -1
    self.type = ExhibitType.None
    self.depositServerID = -1
end

function ExhibitBoxInfo:SetServerID(serverID)
