    return self.slotID
end

function ExhibitBoxInfo:GetDepositServerID()
   return self.depositServerID
end

function ExhibitBoxInfo:SetDepositServerID(ID)
    self.depositServerID=ID
    local active=ID>0
    if PersonalHomeDataManager:Get():GetPersonalHomeData():GetRID()~=PlayerDataManager:Get():GetPlayerRID() then
        active=false
    end
    if self.type == ExhibitType.NormalExhibit or self.type == ExhibitType.Trophy or  self.type == ExhibitType.Car or self.type == ExhibitType.PreviewCar then
        self.IBox:SetActive(active)
        if active then
            self.IBox:OperationConfig(true,true)
        else
            self.IBox:OperationConfig(false,false)
        end
    else
        self.IBox:OperationConfig(false,true)
    end
end

function ExhibitBoxInfo:Reset()
    if self.IBox~=nil  then
        --self.IBox:SetActive(false)
        UIUtil:GameobjectLocalPosition(self.IBox:GetBoxGameObject(), Vector3.zero)
        mono.SetLayerName(self.IBox:GetBoxGameObject(),"Default")
    end
end

function ExhibitBoxInfo:Recycle()
    self.serverID = -1
    self.slotID = -1
    self.type = ExhibitType.None
    self.depositServerID = -1
end

---@class ExhibitBoxMgr
ExhibitBoxMgr = class("ExhibitBoxMgr")

function ExhibitBoxMgr:initialize()
    ---@type table<number,ExhibitBoxInfo> @  table<实体ID,ExhibitBoxInfo>
    self.boxDic={}
    self.Root = nil
    self.entityID=0
end

function ExhibitBoxMgr:Get()
    if self.Instance == nil then self.Instance = ExhibitBoxMgr() end
    return self.Instance
end

function ExhibitBoxMgr:CreateEntityID()
    self.entityID = self.entityID+1
    return self.entityID
end

function ExhibitBoxMgr:GetBox(root,serverId, slotID,type,size)
    local boxGo= UIUtil.GetChild("Box", root)
    if boxGo then
        ---@type IBox
        local ibox = UIUtil.GetGameobjectComponent(boxGo,typeof(CSPersonalHomeBox))
        local buttonScale = UIUtil.GetGameobjectComponent(boxGo, typeof(CSButtonScale))
        local collider = UIUtil:AddGameobjectComponent(boxGo,typeof(CS.UnityEngine.BoxCollider))
        collider.size=size
        buttonScale.enabled=false
        ibox:SetActive(false)
        ---@type ExhibitBoxInfo
        local boxInfo=  self.boxDic[ibox:GetEntityID()]
        boxInfo:SetServerID(serverId)
        boxInfo:SetSlotID(slotID)
        boxInfo:SetType(type)
        boxInfo:SetDepositServerID(-1)
        return boxGo
    else
        return  self:CreateBox(root, serverId, slotID,type,size)
    end
end

function ExhibitBoxMgr:CreateBox(root, serverId, slotID,type,size)
    local entityID = self:CreateEntityID()
    local boxGo =GameObject("Box")--SetParentGameObject
    UIUtil.SetParentGameObject(root, boxGo,true)
    ---@type IBox
    local ibox = UIUtil:AddGameobjectComponent(boxGo,typeof(CSPersonalHomeBox))
    local collider = UIUtil:AddGameobjectComponent(boxGo,typeof(CS.UnityEngine.BoxCollider))
    if type ~= ExhibitType.Trophy and type~=ExhibitType.Car and type~=ExhibitType.PreviewCar then
        collider.enabled=false
    end
    collider.size=size
    local buttonScale = UIUtil.GetGameobjectComponent(boxGo, typeof(CSButtonScale))
    buttonScale.enabled=false
    ibox:SetEntityID(entityID)
    ibox:SetActive(false)
    ---@type ExhibitBoxInfo
    local boxInfo= ExhibitBoxInfo()
    boxInfo.IBox = ibox
    boxInfo:SetServerID(serverId)
    boxInfo:SetSlotID(slotID)
    boxInfo:SetType(type)
    boxInfo:SetDepositServerID(-1)
    self.boxDic[entityID] = boxInfo
    return boxGo
end
---@return ExhibitBoxInfo
function ExhibitBoxMgr:GetBoxInfoByServerIdSlot(serverID, slotID)
    for i, v in pairs(self.boxDic) do
        if v:GetServerID()==serverID and v:GetSlotID()==slotID then
            return v
        end
    end
    return nil
end

function ExhibitBoxMgr:GetBoxInfo(entityID)
    return self.boxDic[entityID]
end

function ExhibitBoxMgr:Recycle()
    for i, boxInfo in pairs(self.boxDic) do
        boxInfo:Recycle()
    end
end

function ExhibitBoxMgr:Destroy()
    self.boxDic={}
    self.entityID = 0
end